/**
 * Asset manifest: stable IDs → exported files under public/assets/ (generated by
 * `npm run art:export`). Entries marked `placeholder` are temporary development art; the
 * release content check rejects them.
 */
export interface IllustrationAsset {
  readonly id: string;
  readonly file: string;
  readonly placeholder: boolean;
}

export interface AssetManifest {
  readonly atlases: Readonly<Record<'light' | 'dark', string>>;
  readonly illustrations: readonly IllustrationAsset[];
  readonly memorial: readonly { readonly id: string; readonly file: string }[];
  /** Animation tags every atlas must contain (cat behavior used by Pixi and DOM). */
  readonly requiredAnimations: readonly string[];
}

const CAT_TAGS = ['idle', 'sleep', 'walk', 'eat', 'play', 'pet', 'lonely', 'sick', 'attention'];

export const assetManifest = {
  atlases: { light: 'sprites-light.json', dark: 'sprites-dark.json' },
  illustrations: [
    { id: 'tech-autocomplete', file: 'technologies/autocomplete.png', placeholder: false },
    {
      id: 'tech-generated-snippets',
      file: 'technologies/generated-snippets.png',
      placeholder: false,
    },
    { id: 'tech-ai-native-ide', file: 'technologies/ai-native-ide.png', placeholder: false },
    { id: 'tech-terminal-agent', file: 'technologies/terminal-agent.png', placeholder: false },
    ...(
      [
        'autonomous-edits',
        'tool-permissions',
        'persistent-instructions',
        'ralph-loop',
        'reviewer',
        'parallel-agents',
        'worktrees',
        'manager-agent',
      ] as const
    ).map((name) => ({ id: `tech-${name}`, file: `technologies/${name}.png`, placeholder: false })),
  ],
  memorial: [
    { id: 'memorial-keyboard', file: 'memorial/keyboard.png' },
    { id: 'memorial-lap', file: 'memorial/lap.png' },
  ],
  requiredAnimations: [
    ...CAT_TAGS.flatMap((tag) => [`cat-${tag}`, `cat-round-${tag}`]),
    'room-back',
    'room-desk',
    'room-monitor',
    'programmer-typing',
    'cat-bowl',
  ],
} as const satisfies AssetManifest;
